Task: A page titled "Release notes" that loads the JSON file feed.json from this site (an array of objects with a text "title" and a text "url"), shows the first 10 as a bulleted list of links, and reloads it by itself every 30 seconds. Show "Loading..." until the first answer and "Could not load the feed." if a request fails.

Your program:
```
type Item = { title: Str, link: Str }

type Model = { round: Int where it >= 0, items: List[Item], loaded: Bool, failed: Bool }

type Msg = Got(Json) | Failed(Str) | Again

fn init() -> Model = Model { round: 0, items: [], loaded: false, failed: false }

fn itemsOf(j: Json) -> List[Item] =
  j
    .list()
    .take(10)
    .map(
      o => Item {
        title: o.get("title").andThen(t => t.str()).unwrapOr("(untitled)"),
        link: o.get("url").andThen(u => u.str()).unwrapOr("#")
      }
    )

fn update(m: Model, msg: Msg) -> Model = match msg {
  Got(j) => m with { items: itemsOf(j), loaded: true, failed: false }
  Failed(e) => m with { failed: true }
  Again => m with { round: m.round + 1 }
}

// a new address each round makes the page ask again
fn fetches(m: Model) -> List[Fetch[Msg]] =
  [Fetch.json("feed.json?round=" ++ m.round.toStr(), j => Got(j), e => Failed(e))]

fn subs(m: Model) -> List[Sub[Msg]] = [Sub.every(30000, Again)]

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Release notes"),
      if m.failed && !m.loaded { Html.para("Could not load the feed.") } else if !m.loaded {
        Html.paragraph("Loading...")
      } else { Html.list(m.items.map(i => Html.link(i.title, i.link))) }
    ]
  )

fn parsed(text: Str) -> Json = match Json.parse(text) {
  Ok(j) => j
  Err(e) => JNull
}

fn sample() -> Json =
  parsed(
    "[{\"title\":\"First\",\"url\":\"https://a.example/1\"},{\"title\":\"Second\"},{\"other\":1}]"
  )

