Task: A page titled "What is new" that loads the JSON file articles.json from this site (an array of objects with a text "headline" and a text "link"), shows the first 10 as a bulleted list of links, and reloads it by itself every 30 seconds. Show "Loading..." until the first answer and "Could not load the feed." if a request fails.

Your program:
```
type Item = { title: Str, link: Str }

type Model = { round: Int where it >= 0, items: List[Item], loaded: Bool, failed: Bool }

type Msg = Got(Json) | Failed(Str) | Again

fn init() -> Model = Model { round: 0, items: [], loaded: false, failed: false }

fn itemsOf(j: Json) -> List[Item] =
  j
    .list()
    .take(10)
    .map(
      o => Item {
        title: o.get("headline").andThen(t => t.str()).unwrapOr("(untitled)"),
        link: o.get("link").andThen(u => u.str()).unwrapOr("#")
      }
    )

fn update(m: Model, msg: Msg) -> Model = match msg {
  Got(j) => m with { items: itemsOf(j), loaded: true, failed: false }
  Failed(e) => m with { failed: true }
  Again => m with { round: m.round + 1 }
}

