fn init() -> Model = Model { a: false }

fn update(m: Model, msg: Msg) -> Model = match msg {
  ToggleA => m with { a: !m.a }
  ToggleB => m with { b: !m.b }
  ToggleC => m with { c: !m.c }
}

fn doneCount(m: Model) -> Int = [m.a, m.b, m.c].count(x => x)

