type Tree = Leaf | Node(Tree, Int, Tree)

fn insert(t: Tree, x: Int) -> Tree
  decreases t
  = match t {
    Leaf => Node(Leaf, x, Leaf)
    Node(l, v, r) => if x < v { Node(insert(l, x), v, r) }
  }

fn depth(t: Tree) -> Int
  ensures result >= 0
  decreases t
  = match t {
    Leaf => 0
    Node(l, _, r) => 1 + depth(l).max(depth(r))
