  [
    Line { a: 0, b: 1, c: 2 },
    Line { a: 3, b: 4, c: 5 },
    Line { a: 6, b: 7, c: 8 },
    Line { a: 0, b: 3, c: 6 },
    Line { a: 1, b: 4, c: 7 },
    Line { a: 2, b: 5, c: 8 },
    Line { a: 0, b: 4, c: 8 },
    Line { a: 2, b: 4, c: 6 }
  ]

