type Msg = Clock(Int) | Seen(Bool) | Got(Str) | Failed(Str)

fn init() -> Model = Model { now: 0, minute: 0, round: 0, text: "", visible: true }

fn pad(n: Int) -> Str = if n < 10 { "0" ++ n.toStr() }

