type Model = { a: Int where it >= 0, b: Int where it >= 0 }

type Msg = ScoreA(Int) | ScoreB(Int) | NewGame

fn init() -> Model = Model { a: 0, b: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  ScoreA(n) => if n > 0 { m with { a: m.a + n } } else { m }
  ScoreB(n) => if n > 0 { m with { b: m.b + n } } else { m }
  NewGame => init()
}

fn leader(m: Model) -> Str = if m.a > m.b { "Team A leads" } else if m.b > m.a {
  "Team B leads"
} else { "Tied" }

fn save(m: Model) -> Str = m.a.toStr() ++ "," ++ m.b.toStr()

fn restore(s: Str) -> Option[Model] = {
  let parts = s.split(",")
  match parts.first() {
    Some(x) => match x.toInt() {
      Some(a) => match parts.drop(1).first() {
        Some(y) => match y.toInt() {
          Some(b) => if a >= 0 && b >= 0 { Some(Model { a: a, b: b }) } else { None }
          None => None
        }
        None => None
      }
      None => None
    }
    None => None
  }
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Team A " ++ m.a.toStr() ++ " : " ++ m.b.toStr() ++ " Team B"),
      Html.paragraph(leader(m)),
      Html.row(
        [
          Html.button("Team A +1", ScoreA(1)),
          Html.button("Team A +2", ScoreA(2)),
          Html.button("Team A +3", ScoreA(3))
        ]
      ),
      Html.row(
        [
          Html.button("Team B +1", ScoreB(1)),
          Html.button("Team B +2", ScoreB(2)),
          Html.button("Team B +3", ScoreB(3))
        ]
      ),
      Html.button("New game", NewGame)
    ]
  )

test startsTied = leader(init()) == "Tied"

test addsPoints = update(update(init(), ScoreA(3)), ScoreA(2)).a == 5

test leaderChanges = leader(update(update(init(), ScoreA(2)), ScoreB(3))) == "Team B leads"

test negativePointsAreIgnored = update(init(), ScoreA(-5)).a == 0

test newGameResets = update(update(init(), ScoreB(2)), NewGame).b == 0

test restoresBothNumbers = restore(save(init())).isSome()

test ignoresNonsense = restore("1").isNone()
```

