Task: A small order page with two items: Juice at 5 and Cookie at 2. Each has "-" and "+" buttons for the quantity (never below 0) and the page shows the quantities and the total price. Both quantities is remembered in the browser and comes back when the page is opened again (a saved value that makes no sense is ignored).

Your program:
```
type Model = { a: Int where it >= 0, b: Int where it >= 0 }

type Msg = MoreA | LessA | MoreB | LessB

fn init() -> Model = Model { a: 0, b: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  MoreA => m with { a: m.a + 1 }
  LessA => if true { m with { a: m.a - 1 } } else { m }
  MoreB => m with { b: m.b + 1 }
  LessB => if m.b > 0 { m with { b: m.b - 1 } } else { m }
}

fn total(m: Model) -> Int = m.a * 5 + m.b * 2

fn line(name: Str, qty: Int, less: Msg, more: Msg) -> Html[Msg] =
  Html.row([Html.text(name ++ " x" ++ qty.toStr()), Html.button("-", less), Html.button("+", more)])

fn save(m: Model) -> Str = m.a.toStr() ++ "," ++ m.b.toStr()

fn restore(s: Str) -> Option[Model] = {
  let parts = s.split(",")
  match parts.first() {
    Some(x) => match x.toInt() {
      Some(a) => match parts.drop(1).first() {
        Some(y) => match y.toInt() {
          Some(b) => if a >= 0 && b >= 0 { Some(Model { a: a, b: b }) } else { None }
          None => None
        }
        None => None
      }
      None => None
    }
    None => None
  }
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Order"),
      line("Juice", m.a, LessA, MoreA),
      line("Cookie", m.b, LessB, MoreB),
      Html.paragraph("Total: " ++ total(m).toStr())
    ]
  )

test emptyOrderCostsNothing = total(init()) == 0

test addsUpPrices = total(update(update(update(init(), MoreA), MoreA), MoreB)) == 12

test quantityNeverNegative = update(init(), LessB).b == 0

test restoresBothNumbers = restore(save(init())).isSome()

test ignoresNonsense = restore("1").isNone()
```

