  Html.col(
    [
      Html.heading("Release notes"),
      if m.failed && !m.loaded { Html.paragraph("Could not load the feed.") } else if !m.loaded {
        Html.paragraph("Loading...")
      } else { Html.list(m.items.map(i => Html.link(i.title, i.link))) }
