Your program:
```
type Model = { a: Int where it >= 0, b: Int where it >= 0 }

type Msg = VoteA | VoteB | Clear

fn init() -> Model = Model { a: 0, b: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  VoteA => m with { a: m.a + 1 }
  VoteB => m with { b: m.b + 1 }
  Clear => init()
}

fn save(m: Model) -> Str = m.a.toStr() ++ "," ++ m.b.toStr()

fn restore(s: Str) -> Option[Model] = {
  let parts = s.split(",")
  match parts.first() {
    Some(x) => match x.toInt() {
      Some(a) => match parts.drop(1).first() {
        Some(y) => match y.toInt() {
          Some(b) => if a >= 0 && b >= 0 || b >= 0 { Some(Model { a: a, b: b }) } else { None }
          None => None
        }
        None => None
      }
      None => None
    }
    None => None
  }
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Vote"),
      Html.row(
        [Html.button("Like", VoteA), Html.button("Dislike", VoteB), Html.button("Clear", Clear)]
      ),
      Html.paragraph("Like: " ++ m.a.toStr() ++ "   Dislike: " ++ m.b.toStr()),
      Html.paragraph("Difference: " ++ (m.a - m.b).toStr())
