type Model = { draft: Str, pending: Str, status: Str }

type Msg = Draft(Str) | Send | Sent(Str) | SendFailed(Str)

fn init() -> Model = Model { draft: "", pending: "", status: "" }

fn update(m: Model, msg: Msg) -> Model = match msg {
  Draft(s) => m with { draft: s }
  Send => if m.draft.trim().isEmpty() || !m.pending.isEmpty() { m } else {
    Model { draft: "", pending: m.draft.trim(), status: "Sending..." }
  }
  Sent(body) => m with { pending: "", status: "Received, thank you." }
  SendFailed(e) => m with { pending: "", status: "Could not send: " ++ e }
}

// the request exists while `pending` holds the text; once it is cleared the same text can be sent again
fn fetches(m: Model) -> List[Fetch[Msg]] = if m.pending.isEmpty() { [] } else {
  [Fetch.post("messages", m.pending, s => Sent(s), e => SendFailed(e))]
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Leave a comment"),
      Html.row([Html.input(m.draft, s => Draft(s)), Html.button("Send", Send)]),
      Html.paragraph(m.status)
    ]
  )

test blankTextIsNotSent = fetches(update(update(init(), Draft("   ")), Send)).isEmpty()

test sendingPostsTheText =
  fetches(update(update(init(), Draft(" hi ")), Send)).len() == 1
    && update(update(init(), Draft(" hi ")), Send).pending == "hi"

test theBoxIsEmptiedAfterSending = update(update(init(), Draft("hi")), Send).draft == ""

test aSecondSendWaitsForTheFirst =
  update(update(update(update(init(), Draft("a")), Send), Draft("b")), Send).pending == "a"

test thanksAfterTheAnswer =
  update(update(update(init(), Draft("a")), Send), Sent("ok")).status == "Received, thank you."

test failureIsReported =
  update(update(update(init(), Draft("a")), Send), SendFailed("HTTP 500")).status ==
    "Could not send: HTTP 500"

test afterwardsNothingIsPending =
  fetches(update(update(update(init(), Draft("a")), Send), Sent("ok"))).isEmpty()
