Task: A rating page titled "Your score" with buttons 1 to 10. It shows the chosen rating as stars drawn with "*" and "-" (for example "***--" for 3 of 5) and the number. Nothing is chosen at first. The rating is remembered in the browser and comes back when the page is opened again (a saved value that makes no sense is ignored).

Your program:
```
type Model = { rating: Int where it >= 0 && it <= 10 }

type Msg = Rate(Int)

fn init() -> Model = Model { rating: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  Rate(n) => if n >= 0 && n <= 10 { m with { rating: n } } else { m }
}

fn stars(n: Int) -> Str = "*".repeat(n.clamp(0, 10)) ++ "-".repeat(10 - n.clamp(0, 10))

fn save(m: Model) -> Str = m.rating.toStr()

fn restore(s: Str) -> Option[Model] = match s.toInt() {
  Some(n) => if n >= 0 && n <= 10 { Some(Model { rating: n }) } else { None }
  None => None
}

