  Html.col(
    [
      Html.heading("Your score"),
      Html.row(List.range(1, 11).map(n => Html.button(n.toStr(), Rate(n)))),
      Html.para(stars(m.rating) ++ "  (" ++ m.rating.toStr() ++ ")")
    ]
  )

test nothingChosenAtFirst = stars(init().rating) == "----------"

test drawsStars = stars(3) == "***-------"

test ratingIsStored = update(init(), Rate(2)).rating == 2

test outOfRangeIsIgnored = update(init(), Rate(14)).rating == 0

test restoresWhatWasSaved = restore(save(init())).isSome()

test ignoresNonsense = restore("x").isNone()
```

